            "/'(?:[^']|'')*'/u",
            static fn (array $matches): string => str_replace('.', $periodPlaceholder, $matches[0]),
            $excelAddress
        );

        // Quoted sheet names may contain dots, so translate them before generic references.
        $excelAddress = (string) preg_replace(
            [
                '/(\'(?:[^\']|\'\')*\')\.([^\.]+):\1\.([^\.]+)/miu',
                '/(\'(?:[^\']|\'\')*\')\.([^\.]+)/miu',
            ],
            [
                '$1!$2:$3',
                '$1!$2',
            ],
            $excelAddress
        );
        $excelAddress = str_replace($periodPlaceholder, '.', $excelAddress);

        // Cell range 3-d reference
        // As we don't support 3-d ranges, we're just going to take a quick and dirty approach
        //  and assume that the second worksheet reference is the same as the first
        $excelAddress = (string) preg_replace(
            [
                '/\$?([^\.\'!]+)\.([^\.\'!]+):\$?([^\.\'!]+)\.([^\.\'!]+)/miu',
